import { AbstractSocialCue } from './SocialCue.js';
export class BlinkingCue extends AbstractSocialCue {
    constructor(animationManager, settings) {
        super(animationManager, settings);
        this.blinkTimeout = null;
    }

    start() {
        const blink = () => {
            this.animationManager.scheduleChange("45", 100, 0, 0);
            setTimeout(() => {
                this.animationManager.scheduleChange("45", 0, 0, 0);
                // Schedule the next blink at a random interval between 1 and 10 seconds
                this.blinkTimeout = setTimeout(blink, Math.random() * 9000 + 1000);
            }, 600); // Adjust the blink duration as needed
        };

        // Start the first blink
        blink();
    }

    stop() {
        clearTimeout(this.blinkTimeout);
        this.animationManager.scheduleChange("45", 0, 0, 0);
    }
}