export class AbstractSocialCue {
    constructor(animationManager, settings) {
        if (new.target === AbstractSocialCue) {
            throw new TypeError("Cannot instantiate an abstract class directly.");
        }
        this.animationManager = animationManager;
        this.settings = settings;
    }

    // Abstract method (needs to be overridden in derived classes)
    start() {
        throw new Error("Method 'start()' must be implemented.");
    }

    // Abstract method (needs to be overridden in derived classes)
    stop() {
        throw new Error("Method 'stop()' must be implemented.");
    }
}
